export function createCampaignUI(ctx){
 const {request,escape:e,toast,modal}=ctx;let owner='',campaigns=[],selected='',detail=null,sheets=[],inviteLinks={},history=[],historySheet='';
 let pending=sessionStorage.getItem('rotom-pending-invite')||'';
 const fragment=new URLSearchParams(location.hash.slice(1));if(fragment.has('convite')){const token=fragment.get('convite');if(/^[A-Za-z0-9_-]{20,100}$/.test(token)){pending=token;sessionStorage.setItem('rotom-pending-invite',pending);}}
 const current=()=>ctx.account()?.id===owner;
 const formField=(label,content)=>`<label class="field full">${label}${content}</label>`;
 const action=(key,label,extra='',style='secondary')=>`<button class="btn ${style}" data-campaign-action="${key}" ${extra}>${label}</button>`;
 async function load(){if(!ctx.account())return;if(owner!==ctx.account().id){campaigns=[];selected='';detail=null;inviteLinks={};owner=ctx.account().id;}campaigns=await request('/campaigns');sheets=await request('/characters');if(!campaigns.some(c=>c.id===selected))selected=campaigns[0]?.id||'';detail=selected?await request('/campaigns/'+selected):null;}
 async function show(){await ctx.flush();await load();ctx.show();}
 window.addEventListener('hashchange',()=>{const token=new URLSearchParams(location.hash.slice(1)).get('convite');if(token&&/^[A-Za-z0-9_-]{20,100}$/.test(token)){pending=token;sessionStorage.setItem('rotom-pending-invite',token);show().catch(error=>toast(error.message));}});
 const date=n=>new Date(n).toLocaleString('pt-BR');
 function render(){
  if(!ctx.account())return `<h1>Campanhas</h1><div class="card"><p>${pending?'Entre na sua conta para aceitar o convite.':'Entre na sua conta para criar ou participar de uma campanha.'}</p>${action('account','Conta e fichas')}</div>`;
  if(!current())return `<h1>Campanhas</h1>${action('refresh','Carregar campanhas')}`;
  const gm=detail?.role==='gm',active=sheets.filter(c=>c.campaignId===selected),mine=sheets.filter(c=>c.ownerId===owner&&c.kind==='player');
  return `<h1>Campanhas</h1>${ctx.hosted?'':'<p class="panel-note">Nesta etapa, a aplicação ainda funciona neste PC. O acesso dos jogadores de outros lugares ficará disponível quando hospedarmos.</p>'}${pending?`<section class="card"><h2>Convite recebido</h2><p>Participar permite ao mestre acessar e editar as fichas que você vincular à campanha. Elas continuam pertencendo a você.</p>${action('accept','Aceitar convite','','primary')}${action('cancel-invite','Descartar convite','','light')}</section>`:''}<div class="grid-two"><section class="card"><h2>Suas campanhas</h2>${campaigns.length?formField('Campanha',`<select id="campaign-select">${campaigns.map(c=>`<option value="${e(c.id)}" ${selected===c.id?'selected':''}>${e(c.name)} · ${c.role==='gm'?'Mestre':'Jogador'}</option>`).join('')}</select>`):'<p>Nenhuma campanha ainda.</p>'}${action('refresh','Atualizar lista','','light')}<form id="join-campaign-form">${formField('Link ou código de convite','<input name="invite" required autocomplete="off" placeholder="Cole o convite recebido">')}<button class="btn secondary" type="submit">Participar</button></form></section><section class="card"><h2>Criar campanha</h2><form id="create-campaign-form">${formField('Nome da campanha','<input name="name" maxlength="160" required>')}<button class="btn primary" type="submit">Criar como mestre</button></form></section></div>${detail?`<section class="card campaign-detail"><h2>${e(detail.name)}</h2><p class="input-note">Seu papel: ${gm?'Mestre':'Jogador'}</p>${gm?`<form id="campaign-invite-form"><div class="fields">${formField('Usos do convite','<input name="uses" type="number" min="1" max="100" value="1" required>')}</div><button class="btn secondary" type="submit">Gerar convite</button>${action('revoke','Revogar convites pendentes','','light')}</form>${inviteLinks[selected]?`<label class="field">Link de convite<input readonly id="campaign-invite-link" value="${e(inviteLinks[selected].url)}"></label><p class="input-note">Expira em ${date(inviteLinks[selected].expiresAt)}. Copie o link para compartilhar com seus jogadores.</p>`:''}`:''}<h3>Participantes</h3>${detail.members.map(m=>`<div class="saved-sheet"><div><strong>${e(m.name)}</strong><small>${m.role==='gm'?'Mestre':'Jogador'}${m.id===owner?' · Você':''}</small></div>${gm&&m.role==='player'?action('remove','Remover da campanha',`data-member="${e(m.id)}"`,'light small'):''}</div>`).join('')}${!gm?action('leave','Sair da campanha','','light'):''}<h3>Fichas da campanha</h3>${active.length?active.map(c=>`<div class="saved-sheet"><div><strong>${e(c.name)}</strong><small>${c.kind==='npc'?'NPC · Só o mestre':e(detail.members.find(m=>m.id===c.ownerId)?.name||'Personagem')} · revisão ${c.version}</small></div>${action('open','Abrir ficha',`data-sheet="${e(c.id)}"`,'primary small')}</div>`).join(''):`<p class="input-note">${gm?'Nenhuma ficha vinculada. Convide os jogadores ou crie um NPC.':'Nenhuma ficha sua vinculada. Fichas dos outros jogadores ficam privadas.'}</p>`}<form id="link-campaign-form">${formField('Sua ficha',`<select name="sheet" required><option value="">Escolha uma ficha da sua conta</option>${mine.map(c=>`<option value="${e(c.id)}">${e(c.name)}${c.campaignId===selected?' · Nesta campanha':c.campaignId?' · Em outra campanha':''}</option>`).join('')}</select>`)}<button class="btn secondary" type="submit" ${mine.length?'':'disabled'}>Vincular ficha à campanha</button></form><p class="input-note">Crie ou importe sua ficha em Conta e fichas. Ao sair da campanha, suas fichas são desvinculadas e o mestre perde o acesso.</p>${gm?`<h3>NPCs</h3><form id="create-npc-form">${formField('Nome do NPC','<input name="name" maxlength="100" required>')}<button class="btn primary" type="submit">Criar ficha de NPC</button></form>`:''}</section>`:''}`;
 }
 function inviteToken(input){let token=input.trim();if(token.includes('://')){const url=new URL(token);token=new URLSearchParams(url.hash.slice(1)).get('convite')||'';}if(!/^[A-Za-z0-9_-]{20,100}$/.test(token))throw Error('Convite inválido. Cole o link completo ou o código recebido.');return token;}
 async function join(token){const result=await request('/join',{method:'POST',body:{token:inviteToken(token)}});selected=result.campaignId;pending='';sessionStorage.removeItem('rotom-pending-invite');if(location.hash.includes('convite'))window.history.replaceState(null,'',location.pathname+location.search);await load();ctx.show();toast('Você entrou na campanha. Agora vincule sua ficha.');}
 async function synchronize(){await ctx.refresh();const opened=ctx.connected();if(opened){const exists=await request('/characters/'+opened.id).catch(error=>{if(error.status===404)return null;throw error;});if(!exists)await ctx.local();else await ctx.open(opened.id,true);}await load();ctx.show();}
 async function showHistory(){await ctx.flush();const c=ctx.connected();if(!c)throw Error('Abra uma ficha da sua conta ou campanha.');historySheet=c.id;history=await request('/characters/'+c.id+'/history');modal('Histórico de edições do mestre',`<p class="input-note">Guardamos apenas edições do mestre em fichas de jogadores, por 8 dias. Desfazer preserva alterações posteriores em outros campos; conflitos são bloqueados.</p>${history.length?history.map(h=>`<article class="history-entry"><h3>${e(h.actorName)} · ${date(h.createdAt)}</h3><p class="input-note">Disponível até ${date(h.expiresAt)}</p><details><summary>${h.changes.length} campos alterados</summary>${h.changes.map(change=>`<p><strong>${e(change.path.join(' / '))}</strong><br>${e(preview(change.before))} → ${e(preview(change.after))}</p>`).join('')}</details>${action('undo','Desfazer esta edição',`data-revision="${e(h.id)}"`)}${action('restore-preview','Resgatar versão anterior',`data-revision="${e(h.id)}"`,'light')}</article>`).join(''):'<p>Nenhuma edição do mestre disponível neste período.</p>'}`);}
 function preview(value){if(typeof value==='string'&&(/^(data:image|local-asset:)/.test(value)))return '[imagem]';const s=typeof value==='string'?value:JSON.stringify(value);return (s||'vazio').slice(0,140);}
 async function restore(id,mode){await ctx.flush();const c=ctx.connected();if(!c||c.id!==historySheet)throw Error('Abra novamente o histórico da ficha atual.');await request(`/characters/${c.id}/history/${id}`,{method:'POST',body:{version:c.version,mode}});await ctx.open(c.id,true);ctx.close();toast(mode==='undo'?'Edição desfeita.':'Versão anterior resgatada.');}
 document.addEventListener('change',async event=>{if(event.target.id!=='campaign-select')return;try{selected=event.target.value;await load();ctx.show();}catch(error){toast(error.message);}});
 document.addEventListener('submit',async event=>{const form=event.target;if(!['create-campaign-form','join-campaign-form','campaign-invite-form','link-campaign-form','create-npc-form'].includes(form.id))return;event.preventDefault();event.stopImmediatePropagation();const button=form.querySelector('[type=submit]');button.disabled=true;try{
  await ctx.flush();const values=new FormData(form);
  if(form.id==='create-campaign-form'){const c=await request('/campaigns',{method:'POST',body:{name:String(values.get('name')).trim()}});selected=c.id;await load();ctx.show();}
  if(form.id==='join-campaign-form')await join(String(values.get('invite')));
  if(form.id==='campaign-invite-form'){const invite=await request(`/campaigns/${selected}/invites`,{method:'POST',body:{uses:Number(values.get('uses'))}});inviteLinks[selected]={...invite,url:location.origin+'/#convite='+encodeURIComponent(invite.token)};ctx.show();}
  if(form.id==='link-campaign-form'){const sheet=sheets.find(c=>c.id===values.get('sheet'));if(!sheet)throw Error('Escolha uma ficha.');await request('/characters/'+sheet.id+'/campaign',{method:'POST',body:{campaignId:selected,version:sheet.version}});await synchronize();toast('Ficha vinculada à campanha.');}
  if(form.id==='create-npc-form'){const name=String(values.get('name')).trim();const c=await request('/characters',{method:'POST',body:{name,kind:'npc',campaignId:selected,data:ctx.blank(name)}});await ctx.refresh();await ctx.open(c.id);toast('NPC criado. A ficha é privada do mestre.');}
 }catch(error){toast(error.message);}finally{button.disabled=false;}},true);
 document.addEventListener('click',async event=>{const b=event.target.closest('[data-campaign-action]');if(!b)return;event.stopImmediatePropagation();b.disabled=true;try{
  const a=b.dataset.campaignAction;
  if(a==='account')ctx.accountPage();
  if(a==='refresh')await show();
  if(a==='accept')await join(pending);
  if(a==='cancel-invite'){pending='';sessionStorage.removeItem('rotom-pending-invite');window.history.replaceState(null,'',location.pathname+location.search);ctx.show();}
  if(a==='open')await ctx.open(b.dataset.sheet);
  if(a==='revoke'){await request(`/campaigns/${selected}/invites`,{method:'DELETE'});delete inviteLinks[selected];ctx.show();toast('Convites pendentes revogados.');}
  if(a==='leave'||a==='remove'){const target=a==='remove'?b.dataset.member:owner;modal(a==='leave'?'Sair da campanha':'Remover participante',`<p>As fichas continuam com o jogador e serão desvinculadas. O mestre perderá acesso a elas.</p>${action('confirm-leave','Confirmar',`data-member="${e(target)}" data-campaign="${e(selected)}"`,'primary')}`);}
  if(a==='confirm-leave'){await ctx.flush();await request(`/campaigns/${b.dataset.campaign}/leave`,{method:'POST',body:{userId:b.dataset.member}});ctx.close();await synchronize();}
  if(a==='history')await showHistory();
  if(a==='undo')await restore(b.dataset.revision,'undo');
  if(a==='restore-preview')modal('Resgatar versão anterior',`<p>Isso substitui a ficha inteira pelo estado anterior à edição selecionada, incluindo alterações posteriores do jogador. Para preservar mudanças em outros campos, use Desfazer esta edição.</p>${action('restore','Resgatar ficha inteira',`data-revision="${e(b.dataset.revision)}"`,'primary')}`);
  if(a==='restore')await restore(b.dataset.revision,'restore');
 }catch(error){toast(error.message);}finally{b.disabled=false;}},true);
 return {render,show,refreshContext:async()=>{if(ctx.connected()?.campaignId)selected=ctx.connected().campaignId;await load();},hasInvite:()=>!!pending,name:()=>current()&&detail?detail.name:'Nenhuma campanha selecionada',pendingBanner:()=>pending?`<section class="card"><h2>Convite recebido</h2><p>Abra Campanhas para aceitar o convite e vincular sua ficha.</p><button class="btn primary" data-nav="campaigns">Abrir campanhas</button></section>`:''};
}
